from dataclasses import dataclass, field
from typing import Optional, Dict, Any

@dataclass
class SynthesisInput:
    text: Optional[str] = None
    ssml: Optional[str] = None

@dataclass
class VoiceSelectionParams:
    language_code: str
    name: Optional[str] = None

@dataclass
class AudioConfig:
    audio_encoding: str = "mp3"
    speaking_rate: Optional[float] = None
    pitch: Optional[float] = None
    volume_gain_db: Optional[float] = None

@dataclass
class TextToSpeechConfig:
    api_key: str
    region: str
    voice: Optional[str] = None
    output_format: Optional[str] = "Audio16Khz32KBitRateMonoMp3" # Azure specific output format

import azure.cognitiveservices.speech as speechsdk
from speech_models import TextToSpeechConfig

def get_speech_config(config: TextToSpeechConfig) -> speechsdk.SpeechConfig:
    speech_config = speechsdk.SpeechConfig(subscription=config.api_key, region=config.region)
    if config.voice:
        speech_config.speech_synthesis_voice_name = config.voice
    if config.output_format:
        speech_config.set_speech_synthesis_output_format(getattr(speechsdk.SpeechSynthesisOutputFormat, config.output_format))
    return speech_config

import azure.cognitiveservices.speech as speechsdk
from speech_client import get_speech_config
from speech_models import TextToSpeechConfig, SynthesisInput

def synthesize_ssml(payload: SynthesisInput, config: TextToSpeechConfig) -> dict:
    speech_config = get_speech_config(config)

    speech_synthesizer = speechsdk.SpeechSynthesizer(speech_config=speech_config, audio_config=None)
    result = speech_synthesizer.speak_ssml_async(payload.ssml).get()

    if result.reason != speechsdk.ResultReason.SynthesizingAudioCompleted:
        raise RuntimeError(f"Azure SSML synthesis failed: {result.cancellation_details.reason}")

    return {'audio_bytes': result.audio_data, 'content_type': 'audio/mpeg'}

import os

def save_audio(audio_bytes: bytes, file_path: str) -> dict:
    try:
        with open(file_path, "wb") as audio_file:
            audio_file.write(audio_bytes)
        return {"status": "success", "message": f"Audio saved to {file_path}"}
    except IOError as e:
        raise RuntimeError(f"Failed to save audio to file {file_path}: {e}")

from google.cloud import translate_v2 as translate

def translate_script(text: str, target_language: str, project_id: str) -> dict:
    client = translate.Client(project=project_id)

    result = client.translate(text, target_language=target_language)

    return {
        "translated_text": result['translatedText'],
        "original_text": result['input'],
        "source_language": result['detectedSourceLanguage']
    }
